let driver;
try {
    driver = await new Builder().forBrowser('firefox').build();
    await driver.get('https://www.riamoneytransfer.com/');
    await driver.manage().setTimeouts({ implicit: 1000 });
    const title = await driver.getTitle();
    assert.ok(title && title.length > 0, 'Page title should be available');
    const button = await driver.wait(
        until.elementLocated(
            By.xpath("//*[contains(normalize-space(.), 'Transfer quote calculator')]//*[normalize-space()='They receive']/following::button[1]")
        ),
        10000
    );
    await driver.wait(until.elementIsVisible(button), 10000);
    assert.ok(button, 'They receive button should be visible');
    await driver.sleep(2000);
    await button.click();
    console.log('Clicked the "They receive" button');
    await driver.sleep(2000);
    const calculator = await driver.wait(
        until.elementLocated(
            By.xpath("//*[contains(normalize-space(.), 'Transfer quote calculator')]")
        ),
        10000
    );
    assert.ok(calculator, 'Transfer quote calculator should remain visible after click');
} finally {
    if (driver) {
        await driver.quit();
    }
}
